				/************************************************
				 * cmnGridSingleFileUpload.js
				 * Created at 2023. 01. 27. 오후 6:38:37.
				 *
				 * @author You Minsang
				 ************************************************/
	
				var util = createCommonUtil();
	
				/************************************************
				 * 전역 변수 선언
				 ************************************************/
	
				// fileIndex의 rowId를 설정합니다.
				var mnRowId = 1;
				// 파일 객체들이 저장되는 공간입니다.
				var moFileStorage = {};
	
				var mbFileOpenBtnClick = false;
				var mbFileChange = false;
	
				/**
				 * UDC 컨트롤이 그리드의 뷰 모드에서 표시할 텍스트를 반환합니다.
				 */
				exports.getText = function() {
					// TODO: 그리드의 뷰 모드에서 표시할 텍스트를 반환하는 하는 코드를 작성해야 합니다.
					return app.getAppProperty("value");
				};
	
				/**
				 * fileIndex 값을 설정합니다.
				 * @return rowId
				 * */
				function newFileIndex() {
					return mnRowId++;
				}
	
				function setUploadFileParameter() {
	
					var host = app.getHostAppInstance();
				        
					/**@type cpr.controls.Grid*/
					var vcGrid = app.getHost().getParent();	
					var voDsList = vcGrid.dataSet;
					
					/**@type cpr.protocols.Submission*/
					var voSubSave = host.lookup(app.getAppProperty("saveSubId"));
	
					var vsKeyColNm = app.getAppProperty("keyColNm");
				    var vsFileNoColNm = app.getAppProperty("fileNoColNm");
				    
					// Key 값으로 적용될 컬럼명
					util.DataMap.setValue(app, "dmFile", "KEY_COLUMN", vsKeyColNm);
					
					// 파일 ID로 사용될 컬럼명
					util.DataMap.setValue(app, "dmFile", "FILE_NO_COLUMN", vsFileNoColNm);
				        
					voSubSave.addParameter("c@"+ vsFileNoColNm, null);
	
					// UPDATED : 행이 수정된 상태 ,INSERTED : 행이 신규로 추가된 상태
					var selectState = cpr.data.tabledata.RowState.UPDATED | cpr.data.tabledata.RowState.INSERTED;
	
					// 신규, 수정 상태 값을 갖는 row를 검색하여 row index 배열을 반환합니다.
					var delRowIdxs = voDsList.getRowStatedIndices(selectState);
	
					for (var i = 0; i < delRowIdxs.length; i++) {
						// rowIndex에 해당하는 row 객체를 반환합니다.
						var row = voDsList.getRow(delRowIdxs[i]);
	
						// 현재 row의 "fileIndex" 속성값을 반환합니다.
						var fileIndex = row.getAttr("fileIndex");
	
						if (fileIndex != null) {
	
							// 컬럼명 "key" 값에 해당하는 값을 반환합니다.
							var keyColVal = row.getValue(vsKeyColNm);
							// fileIndex에 해당하는 파일 객체입니다.
							var file = moFileStorage[fileIndex];
	
							if (file !== null) {
								// 전송 시 추가로 전달되는 파라미터에 파일을 추가합니다.
								// 삭제된 파일은 null 값을 전달합니다.
								voSubSave.addFileParameter("f"+app.getAppProperty("fileNoColNm")+"@" + keyColVal, file);
							} else {
								voSubSave.addParameter("f"+app.getAppProperty("fileNoColNm")+"@" + keyColVal, null);
	
							}
						}
					}
	
					// 삭제된 행 파일 처리
					var delRowIdxs = voDsList.getRowStatedIndices(cpr.data.tabledata.RowState.DELETED);
	
					for (var i = 0; i < delRowIdxs.length; i++) {
						// rowIndex에 해당하는 row 객체를 반환합니다.
						var row = voDsList.getRow(delRowIdxs[i]);
	
						// 컬럼명 "key" 값에 해당하는 값을 반환합니다.
						var keyColVal = row.getValue(vsKeyColNm);
	
						voSubSave.addParameter("f"+app.getAppProperty("fileNoColNm")+"@" + keyColVal, null);
					}
	
					voSubSave.addRequestData(app.lookup("dmFile"));
	
					voSubSave.addEventListenerOnce("submit-success", function(e) {
						mnRowId = 1;
						moFileStorage = {};
	
						voSubSave.removeRequestData("dmFile");
						voSubSave.removeAllFileParameters();
					});
	
					// 부모 화면에서 저장동작 처리
				}
				exports.setUploadFileParameter = setUploadFileParameter;
	
				function bytesToSize(bytes) {
					var sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
					if (bytes == 0) return '0 Byte';
					var i = parseInt(Math.floor(Math.log(bytes) / Math.log(1024)));
					return Math.round(bytes / Math.pow(1024, i), 2) + ' ' + sizes[i];
				}
	
				//파일 다운로드 요청을 보낸다.
				function doDownFile() {
	
					var voDsFile = app.lookup("dsFile");
	
					// 조회를 위한 파일 정보 조회
					util.DataMap.setValue(app, "dmParam", "strAtfino", app.getAppProperty("fileNo"));
					util.DataMap.setValue(app, "dmParam", "strMngSn", "1");
				    
					util.Submit.send(app, "subList", function(pbSuccess) {
						if (pbSuccess) {           
							if (voDsFile.getRowCount() < 1) return false;            
				            
				            var strFilePath = voDsFile.getValue(0, "STRG_COURS_NM") + voDsFile.getValue(0, "STRG_FILE_NM");
				            var strFileNm = voDsFile.getValue(0, "REAL_FILE_NM");
				            var strFileSz = voDsFile.getValue(0, "FILE_SZ");
				    
							util.DataMap.setValue(app, "dmDown", "strFilePath", strFilePath);
							util.DataMap.setValue(app, "dmDown", "strFileNm", strFileNm);
							util.DataMap.setValue(app, "dmDown", "strFileSz", bytesToSize(strFileSz));
				           
							util.Submit.send(app, "subCheckExist", function(pbSuccess) {
								if (pbSuccess) {
									util.Submit.send(app, "subDownLoad", function(pbSuccess) {
	
									});
								}
							});
						}
	
					});
				}
	
				function checkAcceptFile(psFileNm){
				    
				    //개발자가 허용한 파일 확장자 체크
				    var psAcceptFile =  app.getAppProperty("acceptFile");    
				    if(ValueUtil.isNull(psAcceptFile)) return true;
				    
				    psAcceptFile = psAcceptFile.toUpperCase();
				    var vbCheck = false;
				    
				    var arrStr = ValueUtil.split(psFileNm, ".");
				    var extStr = arrStr[arrStr.length - 1].toUpperCase();
				    
				    if(psAcceptFile.indexOf(extStr) != -1){
				         vbCheck = true;
				    }    
				    
				    if (!vbCheck) {
				        util.Msg.alert(app, "ERR-M007", extStr);
				                
				        return false;
				    }
				    
				    return true;   
				}
	
