				function onFldRemovebuttonClick(e) {
				    var fld = e.control;
				    
				    var selFiles = fld.getSelection();
				    
				    var dsFile = app.lookup("dsFile");
				    
				    for (var i = 0; i < selFiles.length; i++) {
				        
				        /** @type Object */
				        var file1 = selFiles[i];
				        
				        for (var j = 0; j < dsFile.getRowCount(); j++) {
				            if (file1["name"] == dsFile.getValue(j, "REAL_FILE_NM")) {
				                dsFile.deleteRow(j);
				                break;
				            }
				        }
				        
				    };
				    
				}
	
