				function bytesToSize(bytes) {
				    var sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
				    if (bytes == 0) return '0 Byte';
				    var i = parseInt(Math.floor(Math.log(bytes) / Math.log(1024)));
				    return Math.round(bytes / Math.pow(1024, i), 2) + ' ' + sizes[i];
				}
	
				/**
				 * 파일 다운로드 요청을 보냅니다
				 * @param {Number} pnMngSn 첨부파일 순번
				 */
				function doDownFile(pnMngSn) {
				    
				    var voRow = app.lookup("dsFile").findFirstRow("MNG_SN == '" + pnMngSn + "'");
				    
				    if (!voRow) return false;
				    
				    var voRowData = voRow.getRowData();
				    
				    var vsSaveFileNm = voRowData["REAL_FILE_NM"]; //저장 파일명
				    var vsFileNm = voRowData["STRG_FILE_NM"]; //파일명
				    //var vsFilePath = voRowData["STRG_COURS_NM"]; //파일경로 
				    var vsAtfino = voRowData["ATFINO"]; //저장 파일명
				    var vsMngSn = voRowData["MNG_SN"]; //저장 파일명
				    
				    //util.DataMap.setValue(app, "dmDown", "strFilePath", vsFilePath + vsFileNm);
				    util.DataMap.setValue(app, "dmDown", "strAtfino", vsAtfino);
				    util.DataMap.setValue(app, "dmDown", "strMngSn", vsMngSn);
				    util.DataMap.setValue(app, "dmDown", "strServerFileNm", vsFileNm);
				    util.DataMap.setValue(app, "dmDown", "strFileNm", vsSaveFileNm);
				    
				    var voSumit = app.lookup("subCheckExist");
				    util.Submit.send(app, "subCheckExist", function(pbSuccess) {
				        if (pbSuccess) {
				            if (voSumit.getMetadata("exist") == "Y") {
				                
				                /*
				                util.Submit.send(app, "subDownLoad", function(pbSuccess) {
				                    if (pbSuccess) {
				                    	var dmMessage = app.lookup("dmMessage");
							        	if (dmMessage.getValue("msg") != null && dmMessage.getValue("msg") != "") {
							        		alert(dmMessage.getValue("msg"));
							        	}
				                    }
				                });
				                */
				                
				                
				                var locArr = location.href.split("/");
				                var contextPath = "";
				                if (locArr[3] != null && locArr[3] != "" && locArr[3] == "ISRY_BackEnd") {
				                    contextPath = "/" + locArr[3];
				                }
				                
				                var dmDown = app.lookup("dmDown");
				                
				                var loc = contextPath + "/isry/itgcm/sysmgmt/file/fileDownWeb.do" +
				                        "?file=" + 
				                        "&filename=" + encodeURIComponent(dmDown.getValue("strFileNm") == null ? "" : dmDown.getValue("strFileNm")) +
				                        //"&path=" + encodeURIComponent(dmDown.getValue("strFilePath") == null ? "" : dmDown.getValue("strFilePath")) +
				                        "&atfino=" + encodeURIComponent(dmDown.getValue("strAtfino") == null ? "" : dmDown.getValue("strAtfino")) +
				                        "&mngSn=" + encodeURIComponent(dmDown.getValue("strMngSn") == null ? "" : dmDown.getValue("strMngSn")) +
				                        "&serverFilename=" + encodeURIComponent(dmDown.getValue("strServerFileNm") == null ? "" : dmDown.getValue("strServerFileNm"));
				            
				                $.ajax({
				                    url: loc,
				                    data: {},
				                    method: "GET",
				                    //dataType: "json",
				                    cache: false,
				                    xhrFields: {
				                        responseType: "blob"
				                    }
				                })
				                .done(function (data, message, xhr) { 
				                    //hideAjaxImage(); 
				                    if (xhr.readyState == 4 && xhr.status == 200) {
				                        // 성공했을때만 파일 다운로드 처리하고
				                        var disposition = xhr.getResponseHeader('Content-Disposition'); 
				                        var filename; 
				                        if (disposition && disposition.indexOf('attachment') !== -1) { 
				                            var filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/; 
				                            var matches = filenameRegex.exec(disposition); 
				                            if (matches != null && matches[1]) filename = matches[1].replace(/['"]/g, ''); 
				                        } 
				                        var blob = new Blob([data]); 
				                        var link = document.createElement('a'); 
				                        link.href = window.URL.createObjectURL(blob); 
				                        link.download = decodeURIComponent(filename); 
				                        link.click(); 
				                    } else {
				                        //실패했을때는 alert 메시지 출력
				                        alert("다운로드에 실패하였습니다."); 
				                    }
				                })
				                .fail(function(xhr, status, errorThrown) {
				                    alert("다운로드에 실패하였습니다.");
				                    //console.log("xhr", xhr);
				                    //console.log("errorThrown", errorThrown);
				                    //console.log("status", status);
				                });
				                
				            }
				        }
				    });
				}
	
