				/**
				 * 파일 업로드
				 * @param {Function} pfCallBack 파일 저장완료 후 콜백함수
				 */
				function doUpload(pfCallBack) {
				    
				    /** @type cpr.controls.FileInput */
				    var vcFld = app.lookup("fld");
				    
				    var vaFiles = vcFld.file; // 업로드된 파일
				    var voDsFile = app.lookup("dsFile");
				    
				    if (vaFiles != null) {
				        
				        var vsAttcFileNo = app.getAppProperty("atfino");
				        var vsAtcmflClNm = app.getAppProperty("atcmflClNm");
				        
				        util.DataMap.setValue(app, "dmParam", "strAtfino", vsAttcFileNo);
				        util.DataMap.setValue(app, "dmParam", "strAtcmflClNm", vsAtcmflClNm);
				        util.DataMap.setValue(app, "dmParam", "strMngSn", "1");
				        
				        util.Submit.send(app, "subList", function(pbSuccess) {
				            
				            if (pbSuccess) {
				                
				                if (vaFiles.constructor.name == "File") {
				                    
				                    if (voDsFile != null) {
				                        for (var i = 0; i < voDsFile.getRowCount(); i++) {
				                            voDsFile.deleteRow(i);
				                        }
				                    }
				                    
				                    util.Submit.send(app, "subDelete", function(pbSuccess) {
				                        if (pbSuccess) {
				                            
				                            util.Submit.addFileParameter(app, "subUpload", vaFiles);
				                            
				                            if(app.getHostAppInstance().id.includes('OffcsSgnngManageWeb')){
				                                app.lookup("subUpload").action = '/isry/itgcm/sysmgmt/file/offcsSgnngUpload.do';
				                            }
				                            
				                            util.Submit.send(app, "subUpload", function(pbSuccess) {
				                                if (pbSuccess) {
				                                    
				                                    var vsBeforeAttcNo = util.DataMap.getValue(app, "dmParam", "strAtfino");
				                                    var vsAttcFileNo = util.DataMap.getValue(app, "dmUpload", "strAtfino");
				                                    if (vsBeforeAttcNo != vsAttcFileNo) {
				                                        AppUtil.setAppProperty(app, "atfino", vsAttcFileNo);
				                                    }
				                                    
				                                    vcFld.clear();
				                                    
				                                    pfCallBack();
				                                    
				                                    getFiles();
				                                }
				                            });
				                        }
				                    });
				                    
				                } else {
				                    pfCallBack();
				                }
				            }
				        });
				        
				    } else {
				        
				        // 파일 삭제
				        if (voDsFile.getRowCount() > 0) {
				                        
				            util.Submit.send(app, "subDelete", function(pbSuccess) {
				                if (pbSuccess) {
				                    pfCallBack();
				                }
				            });
				        } else {
				            pfCallBack();
				        }       
				    }    
				}
	
				/**
				 * 첨부파일 키값으로 파일을 가져옵니다.
				 * @param {Function} pfCallBack? 파일 조회 완료 후 콜백함수
				 */
				function getFiles(pfCallBack) {
				    
				    var vcFld = app.lookup("fld");
				    var vcFiles = vcFld.file;
				    var voDsFile = app.lookup("dsFile");
				    var vsAttcFileNo = app.getAppProperty("atfino");
				    var vsAtcmflClNm = app.getAppProperty("atcmflClNm");
				    
				    // 기존 표시된 파일 제거
				    if (vcFiles != null) {
				        vcFld.value = null; // remove-file 이벤트를 발생시키지 않는다.
				    }
				    
				    util.DataMap.setValue(app, "dmParam", "strAtfino", vsAttcFileNo);
				    util.DataMap.setValue(app, "dmParam", "strAtcmflClNm", vsAtcmflClNm);
				    
				    util.Submit.send(app, "subList", function(pbSuccess) {
				        if (pbSuccess) {
				                    
				            var dmDown = app.lookup("dmDown");
				            if (dmDown != null) {
				                dmDown.clear();
				            }
				            
				            /** @type cpr.data.DataSet */
				            var dsFile = app.lookup("dsFile");
				            
				            if (dsFile != null && dsFile.getRowCount() > 0) {
				                var strFilePath = dsFile.getValue(0, "STRG_COURS_NM") + dsFile.getValue(0, "STRG_FILE_NM");
				                var strFileNm = dsFile.getValue(0, "REAL_FILE_NM");
				                var strFileSz = dsFile.getValue(0, "FILE_SZ");
				                var strExtnNm = dsFile.getValue(0, "FILE_EXTN_NM");
				                var strAtfino = dsFile.getValue(0, "ATFINO");
				                var strMngSn = dsFile.getValue(0, "MNG_SN");
				                var strServerFileNm = dsFile.getValue(0, "STRG_FILE_NM");
				                
				                var locArr = location.href.split("/");
				               
				                var contextPath = "";
				                if (locArr[3] != null && locArr[3] != "" && locArr[3] == "ISRY_BackEnd") {
				                    contextPath = "/" + locArr[3];
				                   
				                }
				                
				                //var realFilePath = contextPath + strFilePath.replace("/nas_data/", "/uploadfiles/").replace("C:/development/fileupload/", "/uploadfiles/").replace("C:\\development\\fileupload\\", "/uploadfiles/").replace(/\\/g, "/");
				                //var realFilePath = util.File.makePreviewURL(app, strFilePath.replace(/\\/g, "/"), strFileNm);
				//                var realFilePath = util.File.makePreviewURL(app, strFileNm, strAtfino, strMngSn, strServerFileNm, "");
				                var realFilePath = "/upfile/" + dsFile.getValue(0, "STRG_COURS_NM").split("\\").join("/") + strServerFileNm;
				                
				                var profile = util.Auth.getUserInfo(app, "PROFILE"); // 서버 PROFILE
				            
				                var domain = "";
				                
				                switch (profile) {
				                    case "local": // 로컬호스트
				                        domain = "http://localhost:8880/ISRY_BackEnd";
				                        break;
				                    case "dev2": // 개발서버 : 톰캣, JBoss
				                        if (location.href.indexOf("/ISRY_BackEnd") > -1) {
				                            domain = "http://10.33.2.59:8880";
				                        } else {
				                            domain = "http://10.33.2.59";
				                        }
				                        break;
				                    case "real1": // 행정망 운영
				                        domain = "https://gov.youthsafety.go.kr";
				                        break;
				                    case "real2": // 인터넷망 운영 
				                        domain = "https://gov.youthsafety.go.kr";
				                        break;
				                    case "pre": // 인터넷망 스테이징 운영 
				                        domain = "https://pre.youthsafety.go.kr";
				                        break;
				                    default:
				                        break;
				                }
				                
				                realFilePath = domain + realFilePath;
				                
				                var file = new cpr.controls.UploadedFile({
				                    name: strFileNm,
				                    size: strFileSz,
				                    type: strExtnNm,
				                    properties: {
				                        filePath: realFilePath
				                    }
				                });
				                vcFld.files = [file];
				                
				                //dmDown.setValue("strFilePath", strFilePath);
				                dmDown.setValue("strFileNm", strFileNm);
				                dmDown.setValue("strFileSz", bytesToSize(strFileSz));
				                dmDown.setValue("strAtfino", strAtfino);
				                dmDown.setValue("strMngSn", strMngSn);
				                dmDown.setValue("strServerFileNm", strServerFileNm);
				                
				                // pdf 미리보기 표시여부
				                var strFileExtnNm = dsFile.getValue(0, "FILE_EXTN_NM");
				                if (strFileExtnNm.toLowerCase() == "pdf" || strFileExtnNm.toLowerCase() == "jpg" || strFileExtnNm.toLowerCase() == "jpeg" || strFileExtnNm.toLowerCase() == "png" || strFileExtnNm.toLowerCase() == "gif") {
				                    app.lookup("grpFileView").getLayout().setColumnVisible(1, true);
				                } else {
				                    app.lookup("grpFileView").getLayout().setColumnVisible(1, false);
				                }
				            }
				            
				            vcFld.value = strFileNm;
				            mbIsFileChange = false;
				            app.getContainer().redraw();
				            
				            if (typeof pfCallBack == "function") {
				                pfCallBack();
				            }
				        }
				    });
				}
