				/*
				 * 루트 컨테이너에서 before-draw 이벤트 발생 시 호출.
				 * 그룹 컨텐츠가 그려지기 직전에 호출되는 이벤트 입니다. 내부 컨텐츠를 동적으로 구성하기위한 용도로만 사용됩니다.
				 */
				function onBodyBeforeDraw( /* cpr.events.CUIEvent */ e) {
				    
				    var voHost = app.getHost();
				    var vnStartTime = app.getAppProperty("startTime");
				    var vnStartMin = app.getAppProperty("startMinute");
				    var vnEndTime = app.getAppProperty("endTime");
				    var vnEndMin = app.getAppProperty("endMinute");
				    var vbHasVal = false;
				    
				    if (vnStartTime) {
				        moBeforeStrDate = moBeforeStrDate.hour(vnStartTime);
				        moStrDate = moStrDate.hour(vnStartTime);
				        moDate["strTime"] = vnStartTime;
				        vbHasVal = true;
				    }
				    
				    if (vnStartMin) {
				        moBeforeStrDate = moBeforeStrDate.minute(vnStartMin);
				        moStrDate = moStrDate.minute(vnStartMin);
				        moDate["strMin"] = vnStartMin;
				        vbHasVal = true;
				    }
				    
				    if (vnEndTime) {
				        moBeforeEndDate = moBeforeEndDate.hour(vnEndTime);
				        moEndDate = moEndDate.hour(vnEndTime);
				        moDate["endTime"] = vnEndTime;
				        vbHasVal = true;
				    }
				    
				    if (vnEndMin) {
				        moBeforeEndDate = moBeforeEndDate.minute(vnEndMin);
				        moEndDate = moEndDate.minute(vnEndMin);
				        moDate["endMin"] = vnEndMin;
				        vbHasVal = true;
				    }
				    
				    checkTime();
				    
				    if (voHost.readOnly) {
				        app.getContainer().getLayout().setColumnVisible(0, false);
				        app.getContainer().getLayout().setColumnVisible(1, true);
				        
				        if (vbHasVal) {
				            app.lookup("optViewTime").value = vnStartTime + "시 " + vnStartMin + "분 ~ " + vnEndTime + "시 " + vnEndMin + "분";
				            if (app.getAppProperty("showTotalTime")) {
				                app.getContainer().getLayout().setColumnVisible(2, true);
				            } else {
				                app.getContainer().getLayout().setColumnVisible(2, false);
				            }
				        } else {
				            app.getContainer().getLayout().setColumnVisible(2, false)
				        }
				        
				    } else {
				        app.getContainer().getLayout().setColumnVisible(0, true);
				        app.getContainer().getLayout().setColumnVisible(1, false);
				        
				        if (app.getAppProperty("showTotalTime")) {
				            app.getContainer().getLayout().setColumnVisible(2, true);
				        } else {
				            app.getContainer().getLayout().setColumnVisible(2, false);
				        }                
				    }
				    
				    var vbRequired = app.getAppProperty("required");
				    var voHostParent = app.getHost().getParent();
				        
				    if (vbRequired) {
				        app.lookup("grpTime").getChildren().forEach(function(each) {
				            if (each instanceof cpr.controls.ComboBox) {
				                each.userAttr("required", "Y");
				            }
				        });
				    }
				}
